{
  "name": "open-code-war",
  "version": "0.2.1",
  "description": "코딩 에이전트 입력량을 겨루는 리더보드 — OpenCode 플러그인 + pi 확장. 프롬프트 내용은 수집하지 않음.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "pi-package",
    "leaderboard",
    "telemetry",
    "coding-agent"
  ],
  "homepage": "https://opencodewar.dev",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/dodohankim/opencodewar.git"
  },
  "license": "BUSL-1.1",
  "type": "module",
  "main": "adapters/opencode/ocw-track.js",
  "scripts": {
    "dev": "npm --prefix backend run dev",
    "dev:setup": "npm --prefix backend install && npm --prefix backend run db:migrate:local && npm --prefix backend run db:seed:local",
    "test": "npm --prefix backend run test",
    "typecheck": "npm --prefix backend run typecheck"
  },
  "files": [
    "adapters/opencode/ocw-track.js",
    "adapters/pi/ocw-track.ts",
    "adapters/README.md",
    "plugin/scripts/track.mjs",
    "plugin/scripts/brief.mjs",
    "plugin/scripts/lib"
  ],
  "pi": {
    "extensions": [
      "adapters/pi"
    ]
  },
  "engines": {
    "node": ">=20"
  }
}
